 Response ship(Fixture f,int qty,long v,String who,String k){return req("POST","/merchant/suborders/"+sub(f)+"/shipments",shipBody(f,qty,"TEST"+k.replace("-","")),who,Map.of("If-Match","\""+v+"\"","Idempotency-Key",k));}
