 @Test void twoParcelsAndExplicitReceiptsConserveQuantity(){var f=paid();String first=shipment(ship(f,1,1,merchant,key()));assertEquals("PARTIALLY_SHIPPED",fulfillment(f,f.u(),"consumer").data().get("fulfillment_status").asString());assertEquals("PARTIALLY_SHIPPED",read("/consumer/orders/"+f.order().id(),f.u()).data().get("status").asString());assertEquals("PARTIALLY_COMPLETED",receive(f,first,2,f.u(),key()).data().get("fulfillment_status").asString());String second=shipment(ship(f,1,3,merchant,key()));var completed=receive(f,second,4,f.u(),key());assertEquals(200,completed.status(),completed.body().toString());assertEquals("COMPLETED",completed.data().get("fulfillment_status").asString());assertEquals("COMPLETED",read("/consumer/orders/"+f.order().id(),f.u()).data().get("status").asString());assertEquals(18,balance(f.offer()));assertEquals(1,db.queryForObject("SELECT count(*) FROM inventory_sale_events WHERE payment_id=?",Integer.class,UUID.fromString(f.payment())));}
 @Test void allShippedWaitsForConsumerNotCarrier(){var f=paid();String h=shipment(ship(f,2,1,merchant,key()));assertEquals("AWAITING_RECEIPT",read("/consumer/orders/"+f.order().id(),f.u()).data().get("status").asString());var t=read("/consumer/shipments/"+h+"/tracking",f.u());assertEquals(200,t.status());assertEquals("UNKNOWN",t.data().get("status").asString());assertTrue(t.data().get("stale").asBoolean());assertEquals(0,t.data().get("events").size());assertEquals("SHIPPED_WAITING_RECEIPT",fulfillment(f,f.u(),"consumer").data().get("fulfillment_status").asString());}
