 @Test void sameMerchantMissingStoreCannotShipOrRead(){var f=paid();String who=identity("MERCHANT",merchantId,List.of("order.read","order.ship"));UUID p=db.queryForObject("SELECT principal_id FROM auth_session WHERE access_token_hash=?",UUID.class,crypto.hash(who));db.update("DELETE FROM principal_store_scope WHERE principal_id=?",p);assertEquals(404,ship(f,1,1,who,key()).status());assertEquals(404,fulfillment(f,who,"merchant").status());}
