 @Test void recipientOnlyForPaidScopedDispatcher(){var f=fixture();assertTrue(fulfillment(f,merchant,"merchant").data().get("delivery_address").isNull());String a=aid(attempt(f.u(),f.payment(),"WECHAT",key()));outcome(f.u(),f.payment(),a,"SUCCEEDED");assertEquals("TEST recipient",fulfillment(f,merchant,"merchant").data().get("delivery_address").get("recipient").asString());String who=identity("MERCHANT",merchantId,List.of("order.read"));assertTrue(fulfillment(f,who,"merchant").data().get("delivery_address").isNull());assertTrue(fulfillment(f,admin,"admin").data().get("delivery_address").isNull());}
 @Test void concurrentWorkersCannotOvershipOrDeadlock()throws Exception{var f=paid();var pool=Executors.newFixedThreadPool(2);try{var start=new CountDownLatch(1);Callable<Response> work=()->{start.await();return ship(f,2,1,merchant,key());};var x=pool.submit(work);var y=pool.submit(work);start.countDown();var statuses=List.of(x.get(20,TimeUnit.SECONDS).status(),y.get(20,TimeUnit.SECONDS).status());assertTrue(statuses.contains(200),statuses.toString());assertTrue(statuses.contains(409),statuses.toString());assertEquals(2L,db.queryForObject("SELECT sum(quantity) FROM shipment_items WHERE suborder_id=?",Long.class,UUID.fromString(sub(f))));}finally{pool.shutdownNow();}}
 @Test void auditFailureRollsBackShipmentAndOutbox(){var f=paid();db.execute("CREATE FUNCTION fail_m44_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='order.ship' THEN RAISE EXCEPTION 'TEST fault';END IF; RETURN NEW; END $$");db.execute("CREATE TRIGGER fail_m44_audit BEFORE INSERT ON audit_event FOR EACH ROW EXECUTE FUNCTION fail_m44_audit()");try{assertEquals(503,ship(f,1,1,merchant,key()).status());assertEquals(0,db.queryForObject("SELECT count(*) FROM shipments WHERE suborder_id=?",Integer.class,UUID.fromString(sub(f))));assertEquals(0,db.queryForObject("SELECT count(*) FROM outbox_event WHERE event_type='ShipmentCreated' AND aggregate_id=?",Integer.class,sub(f)));}finally{db.execute("DROP TRIGGER fail_m44_audit ON audit_event");db.execute("DROP FUNCTION fail_m44_audit()");}}
 @Test void malformedAndMissingPreconditionRejected(){var f=paid();assertEquals(428,req("POST","/merchant/suborders/"+sub(f)+"/shipments",shipBody(f,1,key()),merchant,Map.of("Idempotency-Key",key())).status());assertEquals(400,ship(f,0,1,merchant,key()).status());assertEquals(400,req("POST","/consumer/suborders/"+sub(f)+"/confirm-receipt",Map.of("shipment_ids",List.of()),f.u(),Map.of("If-Match","\"1\"","Idempotency-Key",key())).status());}
 @Test void immutableFactsCannotBeEditedOrDeleted(){var f=paid();String h=shipment(ship(f,2,1,merchant,key()));assertThrows(Exception.class,()->db.update("UPDATE shipments SET tracking_no='TAMPERED' WHERE id=?",UUID.fromString(h)));assertThrows(Exception.class,()->db.update("DELETE FROM shipment_items WHERE shipment_id=?",UUID.fromString(h)));assertThrows(Exception.class,()->db.update("UPDATE suborders SET fulfillment_status='COMPLETED',version=version+1 WHERE id=?",UUID.fromString(sub(f))));}

 @Test void foreignOrderItemAndParcelRejected(){var f=paid();String u=consumer();var ord=order(u,q(u,f.offer(),List.of()),key());var other=new Fixture(u,f.offer(),ord,pid(ord));String a=aid(attempt(u,other.payment(),"WECHAT",key()));outcome(u,other.payment(),a,"SUCCEEDED");ship(other,1,1,merchant,key());var invalid=req("POST","/merchant/suborders/"+sub(f)+"/shipments",shipBody(other,1,"TEST"+key().replace("-","")),merchant,Map.of("Idempotency-Key",key(),"If-Match","\"1\""));assertEquals(404,invalid.status());String h=shipment(ship(f,2,1,merchant,key()));assertEquals(404,receive(other,h,2,other.u(),key()).status());}
 @Test void wholeSuborderMixedStoreScopeMustBeGranted(){String first=ready(),u=consumer();shipping();String i=addFor(u,first);UUID scopedPrincipal=db.queryForObject("SELECT principal_id FROM auth_session WHERE access_token_hash=?",UUID.class,crypto.hash(merchant));db.update("INSERT INTO principal_store_scope VALUES (?,?,?)",scopedPrincipal,merchantId,otherStore);UUID saved=store;store=otherStore;String second=ready();store=saved;db.update("DELETE FROM principal_store_scope WHERE principal_id=? AND store_id=?",scopedPrincipal,otherStore);String j=addFor(u,second);var quote=req("POST","/consumer/checkout/quotes",Map.of("cart_item_ids",List.of(i,j),"address_id",addressFor(u)),u,Map.of("Idempotency-Key",key()));assertEquals(200,quote.status(),quote.body().toString());var order=order(u,quote.data().get("quote_id").asString(),key());var f=new Fixture(u,first,order,pid(order));String a=aid(attempt(u,f.payment(),"WECHAT",key()));outcome(u,f.payment(),a,"SUCCEEDED");assertEquals(404,fulfillment(f,merchant,"merchant").status());assertEquals(404,ship(f,1,1,merchant,key()).status());UUID p=db.queryForObject("SELECT principal_id FROM auth_session WHERE access_token_hash=?",UUID.class,crypto.hash(merchant));db.update("INSERT INTO principal_store_scope VALUES (?,?,?)",p,merchantId,otherStore);assertEquals(200,fulfillment(f,merchant,"merchant").status());}
 @Test void parentAggregatesAcrossMerchantsAndReceiptStaysLocal(){String first=ready(),u=consumer();shipping();String i=addFor(u,first);UUID savedMerchant=merchantId,savedStore=store;String savedToken=merchant;merchantId=UUID.randomUUID();store=UUID.randomUUID();db.update("INSERT INTO merchant VALUES (?,'TEST second','ACTIVE')",merchantId);db.update("INSERT INTO merchant_store(id,merchant_id,name) VALUES (?,?,'TEST second')",store,merchantId);merchant=identity("MERCHANT",merchantId,List.of("offer.read","offer.write","inventory.adjust","order.read","order.ship"));String second=ready(),secondToken=merchant;shipping();String j=addFor(u,second);merchantId=savedMerchant;store=savedStore;merchant=savedToken;var quote=req("POST","/consumer/checkout/quotes",Map.of("cart_item_ids",List.of(i,j),"address_id",addressFor(u)),u,Map.of("Idempotency-Key",key()));assertEquals(200,quote.status());var ord=order(u,quote.data().get("quote_id").asString(),key());String payment=pid(ord),attempt=aid(attempt(u,payment,"WECHAT",key()));outcome(u,payment,attempt,"SUCCEEDED");String sub1=db.queryForObject("SELECT id FROM suborders WHERE order_id=? AND merchant_id=?",UUID.class,UUID.fromString(ord.id()),merchantId).toString(),sub2=db.queryForObject("SELECT id FROM suborders WHERE order_id=? AND merchant_id<>?",UUID.class,UUID.fromString(ord.id()),merchantId).toString();String item1=db.queryForObject("SELECT id FROM order_items WHERE suborder_id=?",UUID.class,UUID.fromString(sub1)).toString(),item2=db.queryForObject("SELECT id FROM order_items WHERE suborder_id=?",UUID.class,UUID.fromString(sub2)).toString();var shipped=req("POST","/merchant/suborders/"+sub1+"/shipments",Map.of("carrier_code","SF","tracking_no","TEST"+key().replace("-",""),"items",List.of(Map.of("order_item_id",item1,"quantity",2))),merchant,Map.of("If-Match","\"1\"","Idempotency-Key",key()));String parcel=shipment(shipped);assertEquals("PARTIALLY_SHIPPED",read("/consumer/orders/"+ord.id(),u).data().get("status").asString());assertEquals(200,req("POST","/consumer/suborders/"+sub1+"/confirm-receipt",Map.of("shipment_ids",List.of(parcel)),u,Map.of("If-Match","\"2\"","Idempotency-Key",key())).status());assertEquals("PARTIALLY_COMPLETED",read("/consumer/orders/"+ord.id(),u).data().get("status").asString());assertEquals("PAID_WAITING_FULFILLMENT",read("/consumer/suborders/"+sub2+"/fulfillment",u).data().get("fulfillment_status").asString());assertEquals(404,read("/merchant/suborders/"+sub1+"/fulfillment",secondToken).status());assertEquals(200,req("POST","/merchant/suborders/"+sub2+"/shipments",Map.of("carrier_code","SF","tracking_no","TEST"+key().replace("-",""),"items",List.of(Map.of("order_item_id",item2,"quantity",2))),secondToken,Map.of("If-Match","\"1\"","Idempotency-Key",key())).status());}
